lication_year": 2025, "type": "preprint", "cited_by_count": 27, "open_access": {"is_oa": true, "oa_status": "green", "oa_url": "https://arxiv.org/pdf/2512.21782", "any_repository_has_fulltext": true}, "primary_location": {"id": "pmh:oai:arXiv.org:2512.21782", "doi": null, "is_oa": true, "landing_page_url": "http://arxiv.org/abs/2512.21782", "pdf_url": "https://arxiv.org/pdf/2512.21782", "source": {"id": "https://openalex.org/S4306400194", "display_name": "arXiv (Cornell University)", "issn_l": "2331-8422", "issn": ["2331-8422"], "is_oa": true, "is_in_doaj": false, "is_core": false, "listed_in": [], "host_organization": "https://openalex.org/I205783295", "host_organization_name": "Cornell University", "host_organization_lineage": ["https://openalex.org/I205783295"], "host_organization_lineage_names": [], "type": "repository"}, "license": "other-oa", "license_id": "https://openalex.org/licenses/other-oa", "version": "submittedVersion", "is_accepted": false, "is_published": false, "raw_source_name": null, "raw_type": "text"}, "abstract": "There has been unprecedented interest in developing agents that expand the boundary of scientific discovery, primarily by optimizing quantitative objective functions specified by scientists. However, for grand challenges in science, these objectives may only be imperfect proxies. We argue that automating objective function design is a central, yet unmet need for scientific discovery agents. In this work, we introduce the Scientific Autonomous Goal-evolving Agent (SAGA) to address this challenge. SAGA employs a bi-level architecture in which an outer loop of LLM agents analyzes optimization outcomes, proposes new objectives, and converts them into computable scoring functions, while an inner loop performs solution optimization under the current objectives. This bi-level design enables systematic exploration of the space of objectives and their trade-offs, rather than treating them as fixed inputs. We demonstrate the framework through a wide range of design applications, including antibiotics, nanobodies, functional DNA sequences, inorganic materials, and chemical processes. Notably, our experimental validation identifies a structurally novel hit with promising potency and safety profiles for E. coli in the antibiotic design task, and three de novo PD-L1 binders in the nanobody design task. These results suggest that automating objective formulation can substantially improve the effectiveness of scientific discovery agents."}]", "excerpt_truncated": true, "source_sha256": "c9967412be6d2f12cc07b3dc75b3e8167faf1100213397dbe2d367d9627d84ee", "verification_required": true, "topic_domain": "unassigned_problem", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["doi:10.48550/arxiv.2508.14111", "openalex:W4415238177", "arxiv:2508.14111", "arxiv:2512.21782"], "source_candidates": ["https://doi.org/10.48550/arxiv.2508.14111", "https://arxiv.org/pdf/2508.14111", "https://arxiv.org/pdf/2512.21782"], "source_candidate_identities": {}}
